import sqlite3
import uuid


class Busy(Exception):
    def __init__(self, retry_after=0):
        super().__init__('busy TEST_ONLY_TOKEN=secret-placeholder')
        self.retry_after = retry_after


class Denied(Exception):
    pass


class ResponseLost(Exception):
    pass


class Cancelled(Exception):
    pass


class Control:
    def __init__(self, *, cancelled=False, cancel_on_wait=False):
        self.time = 0.0
        self.cancelled = cancelled
        self.cancel_on_wait = cancel_on_wait
        self.waits = []

    def now(self):
        return self.time

    def wait(self, delay):
        self.waits.append(delay)
        self.time += delay
        if self.cancel_on_wait:
            self.cancelled = True
            raise Cancelled('caller cancelled')


class Backend:
    def __init__(self, path, schedule=(), *, deduplicates=True):
        self.path = path
        self.schedule = list(schedule)
        self.deduplicates = deduplicates
        self.calls = []
        with sqlite3.connect(path) as db:
            db.execute('CREATE TABLE IF NOT EXISTS deliveries '
                       '(identity TEXT PRIMARY KEY, payload TEXT NOT NULL, receipt TEXT NOT NULL)')

    def send(self, identity, payload):
        self.calls.append((identity, payload))
        action = self.schedule.pop(0) if self.schedule else None
        if isinstance(action, Exception):
            raise action
        key = identity if self.deduplicates else str(uuid.uuid4())
        with sqlite3.connect(self.path) as db:
            db.execute('BEGIN IMMEDIATE')
            existing = db.execute('SELECT payload, receipt FROM deliveries WHERE identity = ?', (key,)).fetchone()
            if existing:
                if existing[0] != payload:
                    raise Denied('identity payload mismatch')
                receipt = existing[1]
            else:
                receipt = 'receipt-' + str(uuid.uuid4())
                db.execute('INSERT INTO deliveries VALUES (?, ?, ?)', (key, payload, receipt))
        if action == 'lost-after-commit':
            raise ResponseLost('response missing TEST_ONLY_TOKEN=secret-placeholder')
        return receipt

    def effects(self):
        with sqlite3.connect(self.path) as db:
            return db.execute('SELECT identity, payload, receipt FROM deliveries ORDER BY identity').fetchall()

