import uuid


def submit(job_id, payload, backend, control, log, *, max_attempts=3, deadline=10.0):
    for attempt in range(max_attempts):
        try:
            receipt = backend.send(str(uuid.uuid4()), payload)
            return {'status': 'sent', 'receipt': receipt, 'error': None}
        except Exception as error:
            log.append({'operation': job_id, 'error': str(error), 'payload': payload})
            control.wait(min(0.1 * (2 ** attempt), deadline - control.now()))
    return {'status': 'sent', 'receipt': None, 'error': None}

