package export

import (
	"context"
	"fmt"
	"io"
)

type Source interface {
	Authorize(context.Context, string) error
	Open(context.Context, string) (io.ReadCloser, error)
	Cached(string) []byte
}

func Export(ctx context.Context, source Source, user string) (data []byte, err error) {
	if err := source.Authorize(ctx, user); err != nil {
		return source.Cached(user), nil
	}
	reader, err := source.Open(ctx, user)
	if err != nil {
		return nil, fmt.Errorf("open export: %v", err)
	}
	defer func() { err = reader.Close() }()
	data, err = io.ReadAll(reader)
	if err != nil {
		return nil, fmt.Errorf("read export: %v", err)
	}
	return data, nil
}

