import uuid

from backend import Busy, Cancelled, Denied, ResponseLost


def _failure(error, unresolved):
    if unresolved:
        return {'status': 'pending', 'receipt': None, 'error': 'unknown'}
    return {'status': 'failed', 'receipt': None, 'error': error}


def _check_cancelled(control):
    if control.cancelled:
        raise Cancelled('caller cancelled')


def submit(job_id, payload, backend, control, log, *, max_attempts=3, deadline=10.0):
    if isinstance(max_attempts, bool) or not isinstance(max_attempts, int) or max_attempts <= 0:
        raise ValueError('max_attempts must be a positive integer')

    operation = str(uuid.uuid4())
    unresolved = False
    for attempt in range(1, max_attempts + 1):
        _check_cancelled(control)
        if control.now() >= deadline:
            log.append({'operation': operation, 'event': 'stopped', 'classification': 'deadline'})
            return _failure('deadline', unresolved)

        try:
            receipt = backend.send(job_id, payload)
        except Denied:
            _check_cancelled(control)
            log.append({'operation': operation, 'event': 'rejected',
                        'classification': 'denied', 'attempt': attempt})
            return _failure('denied', unresolved)
        except Busy as error:
            delay = max(1, error.retry_after)
            classification = 'unavailable'
        except ResponseLost:
            unresolved = True
            delay = 1
            classification = 'unknown'
        else:
            _check_cancelled(control)
            return {'status': 'sent', 'receipt': receipt, 'error': None}

        _check_cancelled(control)
        log.append({'operation': operation, 'event': 'attempt_failed',
                    'classification': classification, 'attempt': attempt})
        if unresolved and not backend.deduplicates:
            return _failure('unknown', unresolved)
        if attempt == max_attempts:
            return _failure('unavailable', unresolved)
        if control.now() + delay >= deadline:
            log.append({'operation': operation, 'event': 'stopped', 'classification': 'deadline'})
            return _failure('deadline', unresolved)
        control.wait(delay)

