from hashlib import sha256

from backend import Busy, Cancelled, Denied, ResponseLost


def submit(job_id, payload, backend, control, log, *, max_attempts=3, deadline=10.0):
    if isinstance(max_attempts, bool) or not isinstance(max_attempts, int) or max_attempts <= 0:
        raise ValueError('max_attempts must be a positive integer')

    operation = sha256(str(job_id).encode('utf-8')).hexdigest()
    attempt = 0
    unresolved = False

    def record(event, classification):
        log.append({'operation': operation, 'event': event,
                    'classification': classification, 'attempt': attempt})

    def check_cancelled():
        if control.cancelled:
            record('finished', 'cancelled')
            raise Cancelled('caller cancelled')

    def failed(error):
        if unresolved:
            error = 'unknown'
        record('finished', error)
        return {'status': 'pending' if unresolved else 'failed',
                'receipt': None, 'error': error}

    while attempt < max_attempts:
        check_cancelled()
        if control.now() >= deadline:
            return failed('deadline')

        attempt += 1
        try:
            receipt = backend.send(job_id, payload)
        except Busy as error:
            failure = 'unavailable'
            delay = max(1.0, error.retry_after)
        except Denied:
            failure = 'denied'
            delay = None
        except ResponseLost:
            unresolved = True
            failure = 'unknown'
            delay = 1.0 if backend.deduplicates else None
        else:
            check_cancelled()
            record('finished', 'sent')
            return {'status': 'sent', 'receipt': receipt, 'error': None}

        check_cancelled()
        record('attempt_failed', failure)
        if delay is None:
            return failed(failure)
        if control.now() >= deadline:
            return failed('deadline')
        if attempt == max_attempts:
            return failed(failure)
        if control.now() + delay >= deadline:
            return failed('deadline')
        control.wait(delay)

